(function(){
'use strict';
// Hand-authored, code-native design frames. Synthetic fixtures only; no ledger or network writes.
const paths={back:'m14 6-6 6 6 6',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 6 6 6-6 6',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',home:'m3 10 9-7 9 7v10H3ZM9 20v-7h6v7',history:'M4 5v5h5M4 10a8 8 0 1 1 0 5M12 7v5l3 2',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M16 4a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-3.9',person:'M19 21v-3a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v3',coffee:'M4 7h12v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5ZM16 8h2a3 3 0 0 1 0 6h-2M7 3v1m4-1v1M3 22h15',dinner:'M4 3v6a2 2 0 0 0 4 0V3M6 3v18M16 3v18M16 3c-4 4-4 10 0 10',wifi:'M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0m-9 4a5 5 0 0 1 6 0M12 20h.01',gear:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',info:'M12 11v6m0-10v.01',lock:'M6 10h12v11H6ZM8 10V7a4 4 0 0 1 8 0v3',cloud:'M7 18a5 5 0 1 1 1-10 7 7 0 0 1 13 3 4 4 0 0 1-2 7M3 3l18 18',swap:'M4 8h16m-4-4 4 4-4 4M20 16H4m4-4-4 4 4 4',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM8 7h8M8 11h8M8 15h4',edit:'m14 5 5 5M4 20l5-1L21 7l-5-5L4 14Z',trash:'M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',logout:'M9 3H3v18h6M9 12h12m-5-5 5 5-5 5',warning:'M12 3 2 21h20ZM12 9v5m0 3v.01',undo:'M4 4v6h6M4 10c4-8 16-5 16 3v6',search:'m16 16 5 5',keyboard:'M3 5h18v14H3ZM7 9h.01M11 9h.01M15 9h.01M7 13h.01M11 13h.01M15 13h.01M7 16h10',delete:'m8 5-6 7 6 7h13V5ZM11 9l6 6m0-6-6 6',mail:'M3 5h18v14H3ZM3 5l9 8 9-8',share:'M12 16V2m-5 5 5-5 5 5M5 10H3v11h18V10h-2',clock:'M12 6v6l4 2',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',circle:'',heart:'M12 20 3 11C-2 4 8 0 12 7c4-7 14-3 9 4Z',bolt:'M13 2 4 14h7l-1 8 10-13h-7Z'};
function icon(name,cls=''){let extra='';if(['info','clock','sun','circle'].includes(name))extra='<circle cx="12" cy="12" r="9"/>';if(name==='gear')extra='<circle cx="12" cy="12" r="3"/>';if(name==='person'||name==='people')extra='<circle cx="9" cy="6" r="4"/>';if(name==='search')extra='<circle cx="10" cy="10" r="7"/>';return `<span class="icon ${cls}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${extra}<path d="${paths[name]||paths.info}"/></svg></span>`}
function go(id,content,cls='',label=''){return `<button class="${cls}" data-go="${id}"${label?` aria-label="${label}"`:''}>${content}</button>`}
const avatar=(name,color='')=>`<span class="avatar ${color}" aria-hidden="true">${name}</span>`;
const pair=(other=false,large=false)=>`<span class="avatar-pair ${large?'pair-large':''}" aria-hidden="true">${avatar(other?'A':'Y',other?'lilac':'')}${avatar(other?'J':'S',other?'lilac':'')}</span>`;
const pill=(s,cls='',ico='')=>`<span class="pill ${cls}">${ico?icon(ico):''}${s}</span>`;
const choice=(yes=true)=>`<span class="selection ${yes?'checked':''}" aria-hidden="true">${yes?icon('check'):''}</span>`;
const top=(title='',back='home',right='')=>`<div class="topbar">${go(back,icon('back'),'round-button','Back')}<strong>${title}</strong>${right||'<span style="width:44px"></span>'}</div>`;
const primary=(text,id,cls='')=>go(id,`${text} ${icon('arrow')}`,`primary ${cls}`);
const secondary=(text,id)=>go(id,text,'secondary');
const bottom=(html,cls='')=>`<div class="bottom-actions ${cls}">${html}</div>`;
const expl=(title,text,type='info',cls='')=>`<div class="explain ${cls}">${icon(type)}<p><strong>${title}</strong>${text}</p></div>`;
const row=(title,sub,tail='',lead='',cls='')=>`<div class="row ${cls}">${lead}<div class="row-main"><strong>${title}</strong>${sub?`<span>${sub}</span>`:''}</div>${tail?`<div class="row-tail">${tail}</div>`:''}</div>`;
const linkrow=(id,title,sub,tail='',lead='')=>go(id,row(title,sub,tail||icon('chevron'),lead),'row-button');
const tabs=(active='home')=>`<nav class="tabbar" aria-label="App tabs">${[['home','home','Home'],['activity','history','Activity'],['people','people','People']].map(([id,ico,label])=>go(id,`${icon(ico)}<span>${label}</span>`,active===id?'active':'')).join('')}</nav>`;
const progress=(n)=>`<div class="flow-progress" aria-label="Setup step ${n} of 4">${[1,2,3,4].map(i=>`<span class="${i<=n?'done':''}"></span>`).join('')}</div>`;
const orb=(cls='',ico='plus')=>`<span class="orb ${cls}" aria-hidden="true">${icon(ico)}</span>`;
const amount=(n)=>`<div class="amount"><span class="currency">€</span>${n}</div>`;
const keypad=()=>`<div class="keypad" aria-label="Illustrative number pad">${['1','2','3','4','5','6','7','8','9',',','0','delete'].map(x=>`<button data-demo="Number-pad layout preview. Use Next to explore the completed amount state." aria-label="${x==='delete'?'Delete digit':x}">${x==='delete'?icon('delete'):x}</button>`).join('')}</div>`;
const bridge=(reverse=false)=>`<div class="balance-bridge"><div class="group-person">${pair(reverse,true)}<strong>${reverse?'Alex + Jo':'You + Sam'}</strong><p>From this group</p></div>${icon('arrow')}<div class="group-person">${pair(!reverse,true)}<strong>${reverse?'You + Sam':'Alex + Jo'}</strong><p>To this group</p></div></div>`;
const switcher=(active)=>`<div class="split-switch" aria-label="Split methods">${[['split','Equally'],['exact','Exact amounts'],['paid-for','For one group']].map(([id,l])=>go(id,l,active===id?'active':'')).join('')}</div>`;
const groupRow=(other,sub,tail)=>row(other?'Alex + Jo':'You + Sam',sub,tail,pair(other));
const groupBlock=(other,locked=true)=>`<div class="group-block ${other?'lilac':''}"><div class="group-block-head"><h3>${other?'Alex + Jo':'You + Sam'}</h3>${icon(locked?'lock':'people')}</div><div class="group-member-line">${avatar(other?'A':'Y',other?'lilac':'')}<span>${other?'Alex':'You'}</span><span class="connector">+</span>${avatar(other?'J':'S',other?'lilac':'')}<span>${other?'Jo':'Sam'}</span></div><p>One balance shared by two people.</p></div>`;
const homeContent=(saved=false,offline=false)=>`<div class="hero-home"><div class="home-head"><div><span class="wordmark">numa<span style="color:#8b702e">.</span></span><span class="home-name">Our place</span></div>${go('settings',icon('gear'),'round-button','Settings')}</div><div class="group-tags">${pair()}<span class="label">You + Sam</span><span class="divider-small"></span>${pair(true)}<span class="label">Alex + Jo</span></div><h1>You + Sam owe<br>Alex + Jo</h1><div class="balance-amount">${amount(saved?'132':'84')}${go('why',icon('arrow'),'round-button','See why you owe this amount')}</div><div class="home-subactions">${go('repay','Record a repayment')}<p class="small">Money changes hands<br>outside Numa.</p></div></div>${offline?`<div class="banner">${icon('cloud')}Saved on this iPhone · 1 pending${go('sync-error','Details')}</div>`:''}${go('expense',`${orb()}<span><strong>Add an expense</strong><small>Who paid? Who was it for?</small></span>`,'orb-action')}<div class="section-title"><h2>Latest at home</h2>${go('activity','See all','text-button')}</div>${linkrow('detail','Dinner together','Alex paid · yesterday','€96.00',icon('dinner','icon-disc orange'))}${linkrow('internet','Internet','Jo paid · 10 September','€72.00',icon('wifi','icon-disc lilac'))}<p class="footnote">${offline?'Your balance includes expenses saved on this device.':'Up to date · Everyone sees the same shared history.'}</p>`;
const screens=[];
function screen(id,section,title,subtitle,content,notes,options={}){screens.push({id,section,title,subtitle,content,notes,...options})}
function notes(lead,purpose,interaction,trust){return {lead,purpose,interaction,trust}}
screen('welcome','Start together','Welcome','One promise. One next step.',`<div class="welcome-logo">numa<span>shared</span></div><h1>Good company.<br>Clear money.</h1><p>Keep the shared bills simple.<br>Get back to living together.</p><div class="welcome-play"><span class="welcome-group">You + Sam</span>${orb('hero-orb')}<span class="welcome-group second">Alex + Jo</span></div>`,notes('A social app that happens to do the maths.','Lead with the benefit of living together, not a calculator, financial dashboard, or feature tour.','A warm, physical sphere introduces the same object used to add expenses on Home. No mandatory animation or carousel.','No signup wall. Create a local household first; connect when ready to share.'),{cls:'welcome',footer:bottom(primary('Create our home','create')+secondary('I have an invite','invite')+'<p class="small muted" style="margin-top:10px;margin-bottom:0">No bank connection. No money moved.</p>')});
screen('create','Start together','Name & currency','Set the household boundary before any money is entered.',`${top('Create a home','welcome')}${progress(1)}<h1>Make yourself<br>at home.</h1><p class="intro">A shared space for your household’s expenses.</p><div class="input-block"><label for="home-name">Household name</label><input readonly class="field" id="home-name" value="Our place" maxlength="48"></div><div class="input-block"><span class="field-label">Household currency</span>${go('currency',`<div class="mock-input"><span>Euro <span class="muted">· EUR</span></span>${icon('chevron')}</div>`,'row-button')}</div>${expl('One home, one currency.','Choose carefully. Your currency is fixed once the household is created. Numa does not convert currencies.','lock')}`,notes('Home starts with something familiar.','Only the household name and explicitly selected currency are required. No decorative onboarding questions.','Currency row opens a searchable native selection list. The next frame shows the committed EUR confirmation.','Currency is a household contract, not a device-locale assumption.'),{footer:bottom(primary('Confirm EUR & continue','setup-people'))});
screen('currency','Start together','Choose a currency','Explicit choice, readable ISO codes.',`${top('Currency','create')}<h1>One currency<br>for your home.</h1><p class="intro">Use the currency you normally pay shared bills in.</p><div class="mock-input" style="font-size:17px;color:var(--muted)">${icon('search')}<span style="flex:1">Search currencies</span></div>${go('create',row('Euro','EUR',choice(true)),'row-button')}<button class="row-button" data-demo="Currency-list appearance preview; this walkthrough uses EUR.">${row('British pound','GBP',choice(false))}</button><button class="row-button" data-demo="Currency-list appearance preview; this walkthrough uses EUR.">${row('US dollar','USD',choice(false))}</button><p class="footnote">Design preview uses EUR throughout. Final implementation lists supported ISO 4217 currencies.</p>`,notes('A decision, not an invisible default.','Code and currency name sit together. EUR is the illustrative selected state.','Selection returns to setup, where the primary action explicitly confirms the currency. Other rows demonstrate selection styling, not an implemented currency conversion.','No exchange rates, conversion, or ability to change currency after household creation.'),{footer:bottom(primary('Use EUR','create'))});
screen('setup-people','Start together','Add your people','People remain individuals, even when they share one budget.',`${top('Your people','create')}${progress(2)}<h1>Who’s at home?</h1><p class="intro">Add the people sharing expenses.<br>You can invite them after setup.</p>${row('You','This is you',pill('You'),avatar('Y'))}${row('Sam','Not invited yet',icon('edit'),avatar('S'))}${row('Alex','Not invited yet',icon('edit'),avatar('A','lilac'))}${row('Jo','Not invited yet',icon('edit'),avatar('J','lilac'))}${go('add-person',`${icon('plus')} Add a person`,'secondary space-top')}<p class="footnote">Names are editable. Everyone records purchases as themselves.</p>`,notes('People first. Budgets second.','A plain list establishes who actually paid or recorded a purchase. The colors preview grouping but labels carry identity.','Add a person opens a focused name entry. No contacts permission or phone number required.','A person is not a budget group. Setup handles that distinction in the next screen.'),{footer:bottom(primary('Continue with 4 people','groups'))});
screen('add-person','Start together','Add a person','An intentional small form, not a contacts-import funnel.',`${top('Add a person','setup-people')}<div class="space-top">${avatar('J','lilac')}</div><h1 class="space-top">What should<br>we call them?</h1><div class="input-block"><label for="person-name">Name</label><input readonly class="field" id="person-name" value="Jo" maxlength="60"></div><p class="intro">You’re adding a name to your household, not sending an invitation yet.</p>`,notes('A name is enough.','Keep entry to one field. Avatar initials are derived, not another personalization task.','A native keyboard and focus behavior belong in SwiftUI; this board previews the name-filled state.','Adding someone does not give them authenticated access.'),{footer:bottom(primary('Save person','setup-people'))});
screen('groups','Start together','Choose budget groups','The essential couple-versus-person distinction.',`${top('Shared budgets','setup-people')}${progress(3)}<h1>Who shares<br>a budget?</h1><p class="intro">A couple can share one balance.<br>Everyone else has their own.</p>${groupBlock(false,false)}${groupBlock(true,false)}${go('groups-edit','Change these groups','text-button')}<p class="footnote">A 50/50 bill is split between these two groups—not four people.</p>`,notes('Make the mental model visible.','Two joined identities share one colored surface and one balance. This is the product’s most important setup concept.','Grouping is chosen before financial history. A separate edit state shows that people can stay single.','No splitting debts within a couple. No regrouping after the first financial history, including voided entries.'),{footer:bottom(primary('Continue with 2 groups','ready'))});
screen('groups-edit','Start together','Edit budget groups','The singleton alternative is equally clear.',`${top('Budget groups','groups')}<h1>Separate, or<br>together?</h1><p class="intro">Choose one person or two people<br>for each shared budget.</p>${row('You + Sam','Together in one budget',choice(true),pair())}${row('Alex','Own budget',choice(true),avatar('A','lilac'))}${row('Jo','Own budget',choice(true),avatar('J','sky'))}${expl('Before the first expense only.','Choose the groups that reflect how you share your money. You can change them until financial history starts.','info')}<p class="small muted">Preview alternative: 3 groups. The main walkthrough continues with 2 couples.</p>`,notes('Singles are not the secondary case.','A single avatar and a linked pair use the same row system. This frame explicitly covers one couple plus two single people.','Production group editing uses person selection with disjoint membership. This frame is a visual alternate, not a persisted topology change.','Historical debt stays with the original group. The restriction must also apply after expenses are voided.'),{footer:bottom(primary('Back to two-couple preview','groups'))});
screen('ready','Start together','Confirm the household','A short, useful review before the first expense.',`${top('One last look','groups')}${progress(4)}<h1>Our place.<br>Our rules.</h1><p class="intro">Four people. Two shared budgets.<br>One less thing to figure out.</p>${row('Household','Our place','',icon('home','icon-disc'))}${row('Currency','Euro · fixed after creation','EUR',icon('lock','icon-disc'))}${row('Your budget','You + Sam','',pair())}${row('Other budget','Alex + Jo','',pair(true))}${expl('Once you add money, groups stay put.','You can still edit names and record corrections. Existing debt will never be quietly moved between people.','lock')}`,notes('Clarity before commitment.','Summarize the three decisions that affect the ledger. No celebratory setup screen that hides consequences.','Create home opens the empty state. Invitations remain a later, optional action.','Both the fixed currency and pre-history grouping boundary are present at the decision point.'),{footer:bottom(primary('Create our home','empty'))});
screen('home','Everyday','Home','The debt is a sentence, not a colored finance metric.',homeContent(),notes('Know where you stand. Then move on.','The top surface says who owes whom. A visible arrow opens the explanation. There is no total-spend dashboard or fake budget ring.','Press the tactile orb or the full “Add an expense” row. A short compression follows the finger; release opens amount entry. Repayment is a separate named button.','€84 = €48 dinner share + €36 internet share. Names—not green/red—carry financial direction.'),{footer:tabs()});
screen('why','Everyday','Why this balance?','An auditable explanation that stays human.',`${top('Your balance','home')}<h1>Here’s the<br>whole picture.</h1>${bridge()}<div class="center">${amount('84')}<p class="small muted" style="margin-top:7px">You + Sam owe Alex + Jo</p></div><div class="section-title"><h2>What makes up €84</h2></div>${linkrow('detail','Dinner together','Your group’s share of €96','€48.00',icon('dinner','icon-disc orange'))}${linkrow('internet','Internet','Your group’s share of €72','€36.00',icon('wifi','icon-disc lilac'))}<div class="number-line"><span>Repayments recorded</span><b>€0.00</b></div>`,notes('The answer includes the working.','A who-to-whom bridge establishes direction. Rows explain the outstanding amount and link to source entries.','Balance on Home and detail share this destination. Recording a repayment is always explicit.','Illustrative two-group ledger: Alex paid €96, Jo paid €72, each split equally. There are no hidden prior balances.'),{footer:bottom(primary('Record a repayment','repay'))});
screen('expense','Add an expense','Amount & description','Begin with the detail people already have in their head.',`${top('Add an expense','home',go('home',icon('close'),'round-button','Cancel expense'))}<h1>What was it for?</h1><div class="input-block"><label for="expense-name">Description</label><input readonly id="expense-name" class="field" value="Dinner together" maxlength="200"></div><div class="number-entry"><span class="currency-chip">Euro · EUR ${icon('lock')}</span>${amount('96<span style="color:#9b9d91">.00</span>')}<div class="amount-note"><span>Paid today</span>${go('expense-meta','Change date','text-button')}</div></div>${keypad()}`,notes('Fast entry without a form wall.','Description, amount, date. That is the first screen. Payer and splitting are revealed at the point they are needed.','In the app, the system decimal pad enters integer minor units; no roulette, swipe-only amount control, or forced orb gesture. This board’s keypad is a layout preview.','This new expense is separate from the existing Home fixture. Sam paid €96 today; its equal split reduces what your group owes by €48.'),{footer:bottom(primary('Who paid?','payer'))});
screen('expense-meta','Add an expense','Expense date & note','Small supporting details without crowding entry.',`${top('Expense details','expense')}<h1>Keep the<br>useful details.</h1><div class="input-block"><span class="field-label">Date paid</span><div class="mock-input"><span>12 September 2026</span>${icon('chevron')}</div></div><div class="input-block"><label for="expense-note">Note · optional</label><input readonly class="field" id="expense-note" value="Dinner after the beach" maxlength="2000"></div>${expl('Visible to your household.','Use notes for context everyone needs. Don’t include card numbers or other sensitive details.','info')}<p class="small muted">Native date picker in implementation.<br>No receipt scan or AI feature in this beta.</p>`,notes('Details earn their space.','A separate date and optional note screen avoids a dense first-entry form.','Native date picker. This concept does not add receipt uploads or OCR.','Authored notes participate in privacy erasure; the amount and historical debt remain.'),{footer:bottom(primary('Keep these details','expense'))});
screen('payer','Add an expense','Who paid?','Actual payer never silently defaults to the recorder.',`${top('Paid by','expense')}<h1>Whose money<br>paid for it?</h1><p class="intro">Choose the person who actually paid<br>the €96.00 bill.</p><button class="row-button" data-demo="Payer-list appearance preview; this walkthrough has Sam selected.">${row('You','Your shared budget',choice(false),avatar('Y'))}</button>${row('Sam','You + Sam',choice(true),avatar('S'))}<button class="row-button" data-demo="Payer-list appearance preview; this walkthrough has Sam selected.">${row('Alex','Alex + Jo',choice(false),avatar('A','lilac'))}</button><button class="row-button" data-demo="Payer-list appearance preview; this walkthrough has Sam selected.">${row('Jo','Alex + Jo',choice(false),avatar('J','lilac'))}</button>${expl('Sam paid. You’re writing it down.','The expense belongs to Sam’s shared budget. The history keeps both names.','info')}`,notes('“Paid by” means paid by.','A clear person list, full names and 44-point tap rows. This is not a picker of budget groups.','Sam is the selected illustrative state. Next goes to who benefited. Native selection keeps the user on this screen until they continue.','Recorder is You; payer is Sam; paying budget is You + Sam. These are three distinct concepts.'),{footer:bottom(primary('Split €96.00','split'))});
screen('split','Add an expense','Split equally','The common household case is the default—not the only option.',`${top('Who was it for?','payer')}<h1>One bill.<br>Two budgets.</h1><p class="intro">Sam paid €96.00. Choose the groups<br>sharing this expense.</p>${switcher('split')}${go('paid-for',groupRow(false,'2 people · one budget',`€48.00`),'row-button')}${go('paid-for',groupRow(true,'2 people · one budget',`€48.00`),'row-button')}<div class="allocation" aria-label="50 percent each"><span></span><span></span></div><p class="benefit-note">50% each, because you share two budgets.<br>Not €24 per person.</p>${expl('Your group gets €48 back.','Sam paid for both groups. Alex + Jo owe your group their €48 share. This reduces your current €84 debt to €36.','swap')}`,notes('Equal means equal between budgets.','One row per group and one allocation strip. No pie chart, individual debt duplication, or confusing percentage sliders.','Exact amounts and For one group are adjacent, secondary split methods. All choices have tap paths.','€96 → €48 + €48. Current debt €84 minus €48 paid on behalf of the other group = €36 remaining.'),{footer:bottom(primary('Review expense','review'))});
screen('exact','Add an expense','Exact amounts','A restaurant bill does not have to be 50/50.',`${top('Who was it for?','payer')}<h1>Split it<br>your way.</h1><p class="intro">Sam paid €96.00.<br>Give each budget its exact share.</p>${switcher('exact')}${groupRow(false,'Your group’s share','€60.00')}${groupRow(true,'Their group’s share','€36.00')}<div class="allocation" aria-label="62.5 percent and 37.5 percent"><span style="flex:5"></span><span style="flex:3"></span></div><div class="number-line"><span>Total allocated</span><b>€96.00</b></div><p class="small muted">All €96.00 accounted for.</p>${expl('Their share is €36.00.','Alex + Jo owe your group €36 for this expense. Your current €84 debt would become €48.','check')}`,notes('Precision without spreadsheet energy.','Editable monetary amounts sit right on each group row. A visible remaining amount replaces a complicated allocation table.','Exact split is an alternate fixture. Its own review shows €60/€36; it never silently becomes the equal split.','Integer amounts must total €96 exactly. See “Incomplete split” for blocked-save treatment.'),{footer:bottom(primary('Review exact split','review-exact'))});
screen('paid-for','Add an expense','Paid for another group','A personal purchase is a split preset, not a second ledger.',`${top('Who was it for?','payer')}<h1>Paid for<br>someone else?</h1><p class="intro">Sam paid €96.00. Which group<br>benefited from the whole purchase?</p>${switcher('paid-for')}${go('paid-for',groupRow(false,'Not included',choice(false)),'row-button')}${go('paid-for',groupRow(true,'Full amount · €96.00',choice(true)),'row-button')}${expl('All €96 goes to Alex + Jo.','Your group paid, but did not benefit. After this entry, Alex + Jo would owe your group €12.','swap')}<p class="footnote">The payer and the benefiting group can be different. That is exactly what this preset is for.</p>`,notes('A common edge case made ordinary.','One selected benefiting group takes 100% of the purchase. It remains the same expense object.','A single-select group list. The review is specific to this preset, not the equal-split review.','Current debt €84 minus €96 paid for the other group = a reversed €12 debt. No red/green direction encoding.'),{footer:bottom(primary('Review this expense','review-paid-for'))});
function reviewScreen(id,title,a,b,result){screen(id,'Add an expense',title,'Read the financial consequence before saving.',`${top('Review expense',id==='review'?'split':id==='review-exact'?'exact':'paid-for')}<div class="space-top">${icon('dinner','icon-disc orange')}</div><h1 style="margin-top:18px">Dinner together</h1><p class="intro" style="margin-bottom:15px">Today · Sam paid · Added by you</p>${amount('96.00')}<div class="receipt">${groupRow(false,'Your group’s share',`€${a}.00`)}${groupRow(true,'Their group’s share',`€${b}.00`)}<div class="receipt-total"><span>Total split</span><b>€96.00</b></div></div><div class="debt-strip">${icon('swap')}<span>${result}</span></div><p class="review-note">You’re recording an expense, not making a payment.</p>`,notes('No financial surprises on Save.','Description, payer, recorder, both allocations and the resulting debt direction fit into one focused review.','Save opens the matching completion state. Back edits the corresponding split method.','The synthetic before-state is always You + Sam owe Alex + Jo €84; each alternate review has its own arithmetic.'),{footer:bottom(primary('Save expense',id==='review'?'saved':id==='review-exact'?'saved-exact':'saved-paid-for'))})}
reviewScreen('review','Review equal split',48,48,'After saving, <strong>You + Sam owe Alex + Jo €36.</strong>');
reviewScreen('review-exact','Review exact split',60,36,'After saving, <strong>You + Sam owe Alex + Jo €48.</strong>');
reviewScreen('review-paid-for','Review paid-for-other',0,96,'After saving, <strong>Alex + Jo owe You + Sam €12.</strong>');
function savedScreen(id,title,result){screen(id,'Add an expense',title,'Confirmation is a ledger result, not a confetti interruption.',`${top('Expense saved','home')}<div class="big-check">${icon('check')}</div><h1 class="center">Written down.<br>Sorted out.</h1><p class="intro center">Dinner together · €96.00<br>Sam paid. You added it.</p><div class="receipt">${row('Your new balance',result,'',icon('swap','icon-disc'))}</div>${expl('Saved on this iPhone.','It will appear for your household after sync. You can leave this screen now.','check')}<p class="footnote">A short Undo appears only while this event is still unsent. After that, corrections stay visible in history.</p>`,notes('Let the result do the celebrating.','One check and the exact resulting balance. No full-screen reward animation or delay before continuing.','In production this is a brief inline confirmation, with Undo above navigation in its own reserved region. The board expands it to show the state clearly.','Undo is only available while an event is unsent and within its allowed window. Sent events use a correction or void.'),{footer:bottom(primary('See updated balance','home')+(id==='saved'?secondary('Preview unsent Undo','undo'):''))})}
savedScreen('saved','Expense saved','You + Sam owe Alex + Jo €36.00');savedScreen('saved-exact','Exact expense saved','You + Sam owe Alex + Jo €48.00');savedScreen('saved-paid-for','Paid-for-other saved','Alex + Jo owe You + Sam €12.00');
screen('home-after-expense','Everyday','Home after an expense','The interface acknowledges the new balance, without changing its grammar.',homeContent().replace('€</span>84','€</span>36').replace('Alex paid · yesterday','Sam paid · today'),notes('Same home. Updated truth.','The debt sentence remains stable while the amount changes. Do not recolor the screen to imply that debt has moral value.','The new expense adds a visible row. The original dinner and internet remain accessible in full history.','The new Sam-paid €96 expense offsets €48 of the original €84 debt, leaving €36.'),{footer:tabs()});
screen('undo','Add an expense','Unsent Undo','A reserved lane prevents the old Undo / orb / repayment collision.',homeContent().replace('€</span>84','€</span>36').replace('Alex paid · yesterday','Sam paid · today'),notes('Undo gets its own space.','The snackbar sits above the tab bar, not on top of the orb or repayment button. It never covers the current debt.','Undo is a full accessible action. After sync or expiry, it disappears and the entry’s correction path remains.','This is a timing state, not a guarantee that every saved event can be removed. The remainder of this board is deterministic preview data.'),{footer:tabs()+`<div class="toast">${icon('check')}Expense saved on this iPhone${go('home','Undo')}</div>`});
screen('detail','Everyday','Expense detail','A small receipt, with who paid and who added it intact.',`${top('Expense','activity',go('correction',icon('edit'),'round-button','Correct expense'))}${icon('dinner','icon-disc orange')}<h1 style="margin-top:18px">Dinner together</h1><p class="intro">11 September 2026</p>${amount('96.00')}<div class="receipt">${row('Paid by Alex','Added by Jo','',avatar('A','lilac'))}${groupRow(false,'50% of the bill','€48.00')}${groupRow(true,'50% of the bill','€48.00')}</div><div class="note-line"><strong>Note</strong><p>Dinner after the beach.</p></div><p class="footnote">Your group owes Alex + Jo €48.00 for this expense.</p>${go('void','Void this expense','text-button setting-warning')}`,notes('A record you can trust.','No receipt-paper gimmick. Strong typographic hierarchy, rules and transparent authorship do the work.','Correct opens a new correction flow; Void opens a distinct confirmation explaining the retained history.','This is the existing Home dinner fixture: Alex paid €96, Jo recorded it. It is not the new Sam-paid expense from the add flow.'),{footer:bottom(secondary('View shared history','activity'))});
screen('internet','Everyday','Bill detail','The same expense system handles household bills.',`${top('Expense','activity')}${icon('wifi','icon-disc lilac')}<h1 style="margin-top:18px">Internet</h1><p class="intro">10 September 2026</p>${amount('72.00')}<div class="receipt">${row('Paid by Jo','Added by Jo','',avatar('J','lilac'))}${groupRow(false,'50% of the bill','€36.00')}${groupRow(true,'50% of the bill','€36.00')}</div><p class="footnote">Your group owes Alex + Jo €36.00 for this expense.</p>`,notes('Bills are not a separate subsystem.','The same detail layout works for dinner, internet or rent. A quiet icon provides recognition, not a new category taxonomy.','Back returns to shared history.','Recurring automatic entries are outside this design scope. The bill is recorded manually.'),{footer:bottom(secondary('View shared history','activity'))});
screen('correction','Everyday','Correct an expense','A correction is a visible event, not a silent rewrite.',`${top('Correct expense','detail')}<h1>Fix the detail.<br>Keep the history.</h1><p class="intro">Dinner together · 11 September</p><div class="input-block"><span class="field-label">Corrected amount</span><div class="mock-input">€90.00</div></div>${groupRow(false,'New equal share','€45.00')}${groupRow(true,'New equal share','€45.00')}<div class="input-block"><span class="field-label">Reason · optional</span><div class="mock-input" style="font-size:16px">The tip was counted twice.</div></div>${expl('€96.00 → €90.00','The original entry stays visible. A new correction adjusts your group’s share from €48 to €45.','history')}`,notes('Trust should survive a mistake.','The previous and new amounts appear together. A reason helps housemates understand the change.','The save label explicitly says correction. Preview advances to a history event that shows the delta.','The total outstanding balance becomes €81: corrected dinner €45 plus internet €36. No destructive replacement.'),{footer:bottom(primary('Save correction','history-corrected'))});
screen('void','Everyday','Void an expense','Destructive-looking actions explain the actual ledger behavior.',`${top('Void expense','detail')}<h1>Remove its effect.<br>Not its history.</h1><p class="intro">Dinner together · €96.00</p>${expl('Your group’s debt falls by €48.','The €36 internet share remains. Both the original expense and this void stay in shared history.','warning','warn')}<p>Use this when the expense should never have counted, such as a duplicate entry.</p><div class="input-block"><span class="field-label">Reason · optional</span><div class="mock-input" style="font-size:16px">Added twice by mistake.</div></div>`,notes('No “delete” that secretly erases trust.','The UI uses “void” and explains the consequence in ordinary language before confirmation.','The board shows a confirmation state only; no live ledger mutation.','A void does not reopen group editing. Financial history has occurred even when its net effect is zero.'),{footer:bottom(primary('Record void','history-void')+secondary('Keep expense','detail'))});
screen('activity','Everyday','Shared history','A readable household log, not a statement dashboard.',`${top('','home',go('expense',icon('plus'),'round-button','Add an expense'))}<h1>Our running tab.</h1><p class="intro" style="margin-bottom:0">Expenses, repayments, and every correction.</p><div class="history-filter">${go('activity','All','active')}${go('history-expenses','Expenses')}${go('history-repayments','Repayments')}</div><div class="history-summary">${icon('swap')}<p>You + Sam owe Alex + Jo <strong>€84.00</strong></p></div><div class="history-day">Yesterday · 11 September</div>${linkrow('detail','Dinner together','Alex paid · added by Jo','€96.00',icon('dinner','icon-disc orange'))}<div class="history-day">10 September</div>${linkrow('internet','Internet','Jo paid · added by Jo','€72.00',icon('wifi','icon-disc lilac'))}<p class="footnote">You’re up to date.<br>Every amount has a person and a story.</p>`,notes('A log for the whole household.','Date groups and payment authorship make the history skimmable. Amounts here are expense totals, not mixed with outstanding debt amounts.','The three filters have separate preview states. A top-right Add button is the tap alternative to Home’s orb.','The main fixture has exactly two expenses and zero repayments. Corrections and voids appear as labeled events, never vanishing rows.'),{footer:tabs('activity')});
screen('history-expenses','Everyday','Expense filter','A quiet filtered state uses the same row grammar.',`${top('Activity','activity')}<h1>Expenses.</h1><div class="history-filter">${go('activity','All')}${go('history-expenses','Expenses','active')}${go('history-repayments','Repayments')}</div><div class="history-day">Yesterday · 11 September</div>${linkrow('detail','Dinner together','Alex paid · added by Jo','€96.00',icon('dinner','icon-disc orange'))}<div class="history-day">10 September</div>${linkrow('internet','Internet','Jo paid · added by Jo','€72.00',icon('wifi','icon-disc lilac'))}`,notes('Filters do not become new screens to learn.','Same list, same dates, same detail destinations.','All returns to the full log; Repayments shows the honest empty state.','Expense amounts are totals. Split shares live one tap deeper.'),{footer:tabs('activity')});
screen('history-repayments','Everyday','No repayments yet','An empty state that explains the next useful action.',`${top('Activity','activity')}<h1>Repayments.</h1><div class="history-filter">${go('activity','All')}${go('history-expenses','Expenses')}${go('history-repayments','Repayments','active')}</div><div class="blank-state">${icon('swap','icon-disc')}<h2 style="margin-top:26px">Nothing to record yet?</h2><p>When money changes hands, write it down here. Numa does not make the transfer.</p></div>`,notes('Never fabricate activity for atmosphere.','The repayment filter is empty for this fixture. Copy explains exactly what the app can and cannot do.','Record opens the same repayment flow as Home.','No banking or implicit payment action.'),{footer:bottom(primary('Record a repayment','repay'))});
screen('history-corrected','Everyday','Correction in history','The changed fact and its author remain findable.',`${top('Activity','activity')}<h1>A clear paper trail.</h1><div class="history-summary">${icon('swap')}<p>You + Sam owe Alex + Jo <strong>€81.00</strong></p></div><div class="history-day">Today · 12 September</div>${row('Dinner corrected','You · €96.00 → €90.00','−€6.00',icon('edit','icon-disc'))}<p class="review-note">“The tip was counted twice.”<br>Your group’s share changed by −€3.00.</p><div class="history-day">Yesterday · 11 September</div>${linkrow('detail','Dinner together','Original entry · corrected','€96.00',icon('dinner','icon-disc orange'))}<div class="history-day">10 September</div>${linkrow('internet','Internet','Jo paid · added by Jo','€72.00',icon('wifi','icon-disc lilac'))}`,notes('Changing your mind leaves a trace.','The correction is an event and the original expense is explicitly labeled corrected.','Open the source expense to inspect original allocations.','−€6 total change gives −€3 per group. Outstanding €84 becomes €81.'),{footer:tabs('activity')});
screen('history-void','Everyday','Void in history','A void changes balances, not the existence of the original event.',`${top('Activity','activity')}<h1>Nothing hidden.</h1><div class="history-summary">${icon('swap')}<p>You + Sam owe Alex + Jo <strong>€36.00</strong></p></div><div class="history-day">Today · 12 September</div>${row('Dinner voided','You · original retained','€96.00',icon('trash','icon-disc'))}<p class="review-note">“Added twice by mistake.”<br>This expense no longer affects balances.</p><div class="history-day">Yesterday · 11 September</div>${row('Dinner together','Original entry · voided','<s>€96.00</s>',icon('dinner','icon-disc orange'))}<div class="history-day">10 September</div>${linkrow('internet','Internet','Jo paid · added by Jo','€72.00',icon('wifi','icon-disc lilac'))}`,notes('A readable audit trail.','Voided entries are labeled in words and struck through. No color-only state.','The app’s correction and void events stay inspectable.','Only the €48 dinner share leaves the balance; €36 internet remains. Group topology remains locked.'),{footer:tabs('activity')});
screen('repay','Record a repayment','Record a repayment','The action is bookkeeping, never a transfer.',`${top('Record repayment','home')}<h1>Already paid<br>some back?</h1><p class="intro" style="margin-bottom:0">Write down money sent outside Numa.</p>${bridge()}<div class="repay-amount"><span class="field-label">Amount repaid · EUR</span>${amount('50.00')}</div><div class="number-line"><span>Owed before</span><b>€84.00</b></div><div class="number-line"><span>Still owed after</span><b>€34.00</b></div>${go('overpay','Preview an overpayment','text-button')}<p class="confirmation-note">Only record this after the money has actually changed hands.</p>`,notes('No ambiguous “Pay” button.','The group-to-group direction precedes the amount. The remaining balance previews the result of a partial repayment.','Amount uses the system number pad in the app. A final named recording action confirms money already moved elsewhere.','€84 owed minus €50 repaid = €34. The app never initiates a bank payment.'),{footer:bottom(primary('Record €50.00 repaid','repaid'))});
screen('overpay','Record a repayment','Overpayment warning','Possible does not mean accidental.',`${top('Record repayment','repay')}<h1>A little more<br>than you owe.</h1><p class="intro">You + Sam → Alex + Jo</p><div class="repay-amount"><span class="field-label">Amount repaid · EUR</span>${amount('100.00')}</div>${expl('This is €16.00 over your balance.','If €100 really changed hands, record it. Alex + Jo will then owe You + Sam €16.00.','warning','warn')}<div class="number-line"><span>Currently owed</span><b>€84.00</b></div><div class="number-line"><span>Extra repaid</span><b>€16.00</b></div><p class="confirmation-note">Check the amount and direction before recording.</p>`,notes('Friction where it prevents a real mistake.','A specific warning names the excess and the reversed resulting debt. It does not reject legitimate overpayment.','Edit returns to the amount; the primary action explicitly includes €100.','€100−€84=€16 owed in the other direction. The same group colors are retained.'),{footer:bottom(primary('Record €100.00 repaid','overpaid')+secondary('Change amount','repay'))});
screen('repaid','Record a repayment','Repayment recorded','The success state shows what is left, not a fake payment receipt.',`${top('Repayment recorded','home')}<div class="big-check">${icon('check')}</div><h1 class="center">€50 written down.</h1><p class="intro center">You + Sam repaid Alex + Jo.<br>Recorded by you, today.</p><div class="receipt"><div class="number-line"><span>Previously owed</span><b>€84.00</b></div><div class="number-line"><span>Repayment</span><b>−€50.00</b></div><div class="receipt-total"><span>Still owed</span><b>€34.00</b></div></div><p class="confirmation-note center">You + Sam still owe Alex + Jo €34.00.<br>No money was moved by Numa.</p>`,notes('A smaller balance, clearly explained.','One confirmation and a three-line reconciliation. No transfer status, bank branding or confetti.','Done opens Home with €34. The receipt remains accessible through history in production.','This is a recorded repayment, not evidence from a bank that a transfer succeeded.'),{footer:bottom(primary('Back to our home','home-repaid'))});
screen('overpaid','Record a repayment','Overpayment recorded','Direction can reverse without changing identity.',`${top('Repayment recorded','home')}<div class="big-check">${icon('check')}</div><h1 class="center">€100 written down.</h1><p class="intro center">You + Sam repaid Alex + Jo.</p>${bridge(true)}<div class="center">${amount('16.00')}<p class="confirmation-note">Alex + Jo now owe You + Sam €16.00.<br>No money was moved by Numa.</p></div>`,notes('A reversed debt is still just a debt.','The bridge reverses, while each group keeps its identity color and name.','The completion is specific to the overpayment branch.','No positive/negative color coding; explicit words express the result.'),{footer:bottom(primary('Back to our home','home'))});
screen('home-repaid','Everyday','Home after repayment','A partial repayment belongs in the same shared history.',homeContent().replace('€</span>84','€</span>34').replace(linkrow('detail','Dinner together','Alex paid · yesterday','€96.00',icon('dinner','icon-disc orange')),linkrow('repaid','Repayment recorded','You + Sam → Alex + Jo','€50.00',icon('swap','icon-disc lime'))),notes('Home stays recognizable.','Only the balance and latest activity change. No dashboard rearrangement or new repayment-only navigation.','The activity row opens the repayment detail.','€34 is the remainder from recording €50 against €84, independent of the add-expense branch.'),{footer:tabs()});
screen('people','Your household','People & budgets','The household is people, not account IDs.',`${top('','home',go('settings',icon('gear'),'round-button','Settings'))}<h1>Our people.</h1><p class="intro">Our place · 4 people · 2 budgets</p>${groupBlock(false)}${groupBlock(true)}<div class="section-title"><h2>Sharing access</h2></div>${linkrow('invite-send','Connect & invite','Use the app together',icon('chevron'),icon('share','icon-disc'))}<p class="footnote">Budgets are fixed after financial history starts. Names and access can still be managed.</p>`,notes('Groups are visible without erasing people.','Shared colored surfaces reflect the same budget ownership used on the balance and split screens.','Invitations are separate from names; connecting an account is not required to see local work.','No reassign-people control after financial history. A departed person’s historic group debt is retained.'),{footer:tabs('people')});
screen('invite-send','Your household','Connect & invite','Authentication happens when it provides a clear benefit.',`${top('Share your home','people')}<h1>Same home.<br>Same page.</h1><p class="intro">Connect your account to invite Sam,<br>Alex and Jo to this household.</p><div class="balance-bridge"><div class="group-person">${pair(false,true)}<strong>You + Sam</strong></div>${icon('plus')}<div class="group-person">${pair(true,true)}<strong>Alex + Jo</strong></div></div>${expl('Your local work comes with you.','Connecting must preserve your expenses, repayments and the order they were recorded in.','lock')}<p class="small muted">No invitation is sent just by connecting.<br>You choose who can join next.</p>`,notes('Give sign-in a job.','This is the transition from a local useful app to a shared one. A compact promise explains why to connect.','The production authentication provider remains the existing project flow. This board does not fabricate Apple sign-in availability or expose live links.','No account overwrite, history loss or silent account merge. Private beta remains owner-only; invite screens are design previews.'),{footer:bottom(primary('Preview connected state','connected')+secondary('Keep using on this iPhone','people'))});
screen('connected','Your household','Invite a housemate','Show the identity being claimed before any link leaves the app.',`${top('Invite a housemate','invite-send')}<h1>A place<br>for everyone.</h1><p class="intro">Choose the person this invitation is for.</p>${go('invite-preview',row('Sam','Joins You + Sam',icon('chevron'),avatar('S')),'row-button')}<button class="row-button" data-demo="Invitation list appearance preview. The share walkthrough demonstrates Sam’s invitation.">${row('Alex','Joins Alex + Jo',icon('chevron'),avatar('A','lilac'))}</button><button class="row-button" data-demo="Invitation list appearance preview. The share walkthrough demonstrates Sam’s invitation.">${row('Jo','Joins Alex + Jo',icon('chevron'),avatar('J','lilac'))}</button>${expl('Invites grant household access.','Only share a person’s invitation with that person. They will see the shared history after joining.','lock')}<p class="footnote">Preview only. No account connected and no real invitations generated.</p>`,notes('Identity should never be guessed from a link.','Each invite is attached to a known person and budget. The preview focuses on Sam.','Share uses the native share sheet only after the authenticated server creates the invite.','This artifact never creates credentials, claims membership, or expands the owner-only beta audience.'),{footer:bottom(secondary('Back to our people','people'))});
screen('invite-preview','Your household','Invitation preview','A shareable action with its scope made explicit.',`${top('Invite Sam','connected')}<div class="space-top">${avatar('S')}</div><h1 class="space-top">Sam’s spot<br>is ready.</h1><p class="intro">Our place · You + Sam budget</p>${row('Joining as Sam','Not a new person','',avatar('S'))}${row('Shared budget','You + Sam','',pair())}${row('Access','Shared expense and repayment history','',icon('lock','icon-disc'))}${expl('Send it only to Sam.','An invitation gives access to this household. Review the recipient in the share sheet.','share')}<p class="footnote">No live link in this design board.</p>`,notes('The last check before sharing.','Person, budget and access scope are visible before opening any share destination.','The prototype action explains that sharing is unavailable here instead of inventing a functioning invite URL.','No unauthorized tester distribution. Link expiry and claim errors require honest recovery states.'),{footer:bottom(`<button class="primary" data-demo="Design preview only. No invitation or household access was created.">${icon('share')} Preview native share action</button>`)});
screen('invite','Your household','Join from invitation','The receiving side verifies person and budget before joining.',`${top('Your invitation','welcome')}<h1>Come on in,<br>Sam.</h1><p class="intro">You’ve been invited to Our place.</p>${groupBlock(false)}<div class="receipt">${row('Joining as','Sam')}${row('Household currency','Euro · EUR')}${row('Shared access','Expenses, repayments and corrections')}</div>${expl('Check this is your identity.','If you are not Sam, don’t join with this invitation. Ask for one made for you.','info')}<p class="small muted">Illustrative invitation. Not a live claim.</p>`,notes('Joining is a consequential identity choice.','The invite preview clearly states who is being claimed, which group owns their balance and which currency applies.','Authentication and claim happen only after confirmation. A real failure never drops the user into an empty household.','No silent new-person duplicate, account crossover, or budget assignment by display name.'),{footer:bottom(primary('Preview joining this home','home')+secondary('This isn’t me','invite-error'))});
screen('invite-error','Important states','Invite unavailable','No dead end and no accidental account switch.',`${top('Invitation','welcome')}<div class="blank-state">${icon('lock','icon-disc')}<h1 style="margin-top:26px">This invite<br>can’t be used.</h1><p>It may have expired or already been claimed. Ask your housemate for a new invitation made for you.</p></div>${expl('Your existing home is safe.','We haven’t changed your account, local expenses, or household membership.','check')}`,notes('Fail closed, explain the way out.','One understandable error and one recovery route. No leaked account details or ambiguous retry spinner.','Ask for a new invite is instruction, not an automatic message. Return to existing home is safe.','Identity and local history remain untouched by a failed claim.'),{footer:bottom(primary('Return to my home','home'))});
screen('settings','Your household','Settings','Quiet utility, still unmistakably Numa.',`${top('Settings','home')}<div class="settings-identity">${avatar('Y')}<div><h2>You</h2><p class="small muted">You + Sam · Our place</p></div></div><div class="settings-section">${linkrow('people','Household','People & shared budgets','',icon('people'))}${row('Currency','Fixed for this household','EUR',icon('lock'))}${linkrow('opening','Opening balance','Bring an existing balance','',icon('receipt'))}${linkrow('appearance','Appearance & motion','Follows your iPhone','',icon('sun'))}${linkrow('sync-error','Sync status','Up to date','',icon('cloud'))}${linkrow('privacy','Privacy & your data','Export, erase, leave','',icon('lock'))}</div><p class="footnote">Numa Shared · Private beta<br>No bank connections. No money transfers.</p>`,notes('The useful parts, with the volume turned down.','Settings returns to native list conventions. Group identity anchors the account context before operational controls.','No invented subscription, notification, analytics or social features.','Appearance follows device accessibility settings. Export and account-erasure actions remain distinct.'),{footer:bottom(secondary('Done','home'))});
screen('appearance','Your household','Appearance & motion','Expressive does not mean inaccessible.',`${top('Appearance','settings')}<h1>Make it<br>feel right.</h1><div class="section-title"><h2>Appearance</h2></div>${row('Use iPhone appearance','Light and dark follow the system','<span class="switch" aria-label="On"></span>',icon('sun'))}${row('Reduce Motion','Follows iPhone settings','System',icon('circle'))}${row('Reduce Transparency','Follows iPhone settings','System',icon('circle'))}<div class="motion-demo">${orb()}<p>Press. Release. Add.<br><span class="muted">A small response to your touch.</span></p></div><button class="secondary space-top" data-motion>Preview orb press</button><p class="footnote">With Reduce Motion, the orb keeps a simple pressed state. Opaque surfaces replace translucent navigation when requested.</p>`,notes('Feel is part of accessibility.','No auto-running, looping or randomly drifting sphere. The orb’s movement exists only as input feedback.','Press compression: about 120 ms; release/open: about 220 ms. One light impact on activation, not every frame. Reduced motion removes spring overshoot.','This board previews light screens. Native dark-mode and real device haptic verification remain implementation work; no false certification.'),{footer:bottom(secondary('Done','settings'))});
screen('opening','Your household','Opening balance','Bring the existing number without inventing a purchase.',`${top('Opening balance','settings')}<h1>Picking up<br>where you left off.</h1><p class="intro">Record what was already owed before<br>you started using Numa.</p>${bridge()}<span class="field-label">Already owed · EUR</span>${amount('84.00')}${expl('This adds to your current balance.','This is not a repayment or a purchase. It creates a visible opening-balance entry. Do not also re-enter the same old expenses.','info')}<p class="small muted">Preview only: if added on top of the example home, €84 would become €168 owed.</p>`,notes('Migration needs its own honest language.','The amount is explicitly an existing debt and the direction is visible. Never call this income, expense or settlement.','Review shows the resulting total before recording. This frame demonstrates setup import; it does not mutate the Home fixture.','Avoid double-counting: choose opening balance OR replay old purchases for the same period, not both.'),{footer:bottom(primary('Review opening balance','opening-review'))});
screen('opening-review','Your household','Review opening balance','The imported number is a visible ledger event.',`${top('Review opening balance','opening')}<h1>A starting point.<br>Not a payment.</h1>${bridge()}<div class="receipt"><div class="number-line"><span>Current example balance</span><b>€84.00</b></div><div class="number-line"><span>Opening balance to add</span><b>€84.00</b></div><div class="receipt-total"><span>Resulting debt</span><b>€168.00</b></div></div>${expl('You + Sam would owe Alex + Jo €168.','Only continue if the opening amount is separate from expenses already in this household.','warning','warn')}`,notes('The arithmetic is the warning.','Shows that adding an opening balance is additive. It never silently replaces the reducer-derived balance.','Recording is a preview-only action.','A real event is appended with explicit authorship, direction, currency and amount.'),{footer:bottom(`<button class="primary" data-demo="Design preview only. No opening balance was recorded.">Record opening balance ${icon('check')}</button>`+secondary('Go back','opening'))});
screen('privacy','Your household','Privacy & data','Precise promises instead of vague reassurance.',`${top('Privacy & data','settings')}<h1>Your data.<br>Your call.</h1><p class="intro">Personal information and shared<br>financial history are different things.</p>${linkrow('export','Export household history','Preview the export scope','',icon('download','icon-disc'))}${linkrow('erase','Erase my personal text','Review what stays and goes','',icon('trash','icon-disc'))}${linkrow('leave','Leave this household','Review access and balance','',icon('logout','icon-disc'))}${expl('Shared debt does not disappear.','Leaving or erasing personal text does not change what a budget group owes. History remains understandable without your authored text.','lock')}`,notes('Privacy is a product flow, not a legal footer.','Separate export, text erasure and departure. The consequences are visible before each action.','Each action has a dedicated review screen. No destructive action is executed in the design board.','Erasure must persist through replay and later exports. Leaving does not redistribute debt to the remaining household.'),{footer:bottom(secondary('Done','settings'))});
screen('export','Your household','Export preview','Choose a clear boundary before creating a file.',`${top('Export history','privacy')}<h1>A copy of the<br>shared record.</h1><p class="intro">Our place · Euro (EUR)</p><ul class="privacy-list"><li>${icon('check')}Expenses, splits and actual payers</li><li>${icon('check')}Recorded repayments and opening balances</li><li>${icon('check')}Visible corrections and voids</li><li>${icon('check')}The household’s derived balances</li></ul>${expl('Previously erased text stays erased.','An export must never restore someone’s removed personal notes or identifying authored text.','lock')}<p class="footnote">Contains household financial information. Save and share it only where appropriate.</p>`,notes('Portability without privacy regression.','A short content manifest makes the export’s scope explicit.','Native file/share destination selection is implementation work; the board creates no financial export.','Sanitized export applies the same erasure rules as replay.'),{footer:bottom(`<button class="primary" data-demo="Design preview only. No financial export was generated.">${icon('download')} Preview export action</button>`)});
screen('erase','Your household','Review personal-text erasure','A consequential action deserves unambiguous language.',`${top('Erase personal text','privacy')}<h1>Know what<br>changes.</h1><ul class="privacy-list"><li>${icon('trash')}Your erasable authored text is removed from shared views and future exports.</li><li>${icon('history')}Expense amounts, splits, repayments and event order remain.</li><li>${icon('lock')}Your group’s existing debts do not change.</li></ul>${expl('This cannot be undone.','Read the scope before continuing. This design preview will not erase anything.','warning','warn')}<p class="small muted">A final confirmation is required in the actual app.</p>`,notes('No euphemisms at a destructive boundary.','Clearly separate personal text from financial record retention. Specific backend-supported scope must remain the authority at implementation.','Final confirmation is deliberate, with no preselected destructive choice. This preview never invokes the operation.','Erasure survives sync, replay, account reconnection and export; it is not just hidden UI text.'),{footer:bottom(`<button class="primary" data-demo="Design preview only. Nothing was erased.">Preview final confirmation</button>`+secondary('Keep my data','privacy'))});
screen('leave','Your household','Review leaving a home','Leaving membership does not move historic balances.',`${top('Leave household','privacy')}<h1>Leaving home<br>doesn’t erase debt.</h1><p class="intro">You’re leaving Our place as You.</p>${row('Your shared budget','You + Sam','',pair())}${row('Current group debt','Owed to Alex + Jo','€84.00',icon('swap','icon-disc'))}${expl('The group keeps its balance.','Your departure does not transfer its debt to Sam or to another group. Financial history stays in the household.','lock')}<p class="small muted">Review any outstanding repayments with your housemates before leaving.</p>`,notes('Departure without silent reassignment.','The current group and its outstanding balance anchor the decision.','A real leave operation requires the project’s membership and account boundary checks. The prototype does not sign out or alter access.','Retired groups can retain nonzero balances. No automatic regrouping or redistribution.'),{footer:bottom(`<button class="primary" data-demo="Design preview only. Household membership was not changed.">Preview leaving confirmation</button>`+secondary('Stay in our home','people'))});
screen('empty','Important states','First expense / all square','A useful empty state, not an empty dashboard.',`<div class="hero-home"><div class="home-head"><div><span class="wordmark">numa.</span><span class="home-name">Our place</span></div>${go('settings',icon('gear'),'round-button','Settings')}</div><div class="group-tags">${pair()}<span class="label">You + Sam</span><span class="divider-small"></span>${pair(true)}<span class="label">Alex + Jo</span></div><h1>All square.<br>Nice place to start.</h1><p style="font-size:15px;max-width:270px">No one owes anyone yet.<br>Let’s keep the shared stuff simple.</p></div>${go('expense',`${orb()}<span><strong>Add your first expense</strong><small>A coffee, a bill, a dinner together.</small></span>`,'orb-action')}<div class="subtle-separator"></div><h2>A home for the little<br>“I’ll get this” moments.</h2><p class="intro">Record who paid and who it was for.<br>We’ll keep the balance clear.</p>${go('opening','Already owe each other money? '+icon('arrow'),'ink-link')}`,notes('Zero should feel settled, not abandoned.','The first state uses a full-color identity surface and one useful action. No fake activity, graphs, trophy or score.','The same orb starts entry. Existing balances have a separate opening-balance path.','No debt is shown until real or explicitly imported history exists.'),{cls:'empty-home',footer:tabs()});
screen('settled','Important states','All settled after repayment','Celebrate proportionally, keep the history.',`<div class="hero-home"><div class="home-head"><div><span class="wordmark">numa.</span><span class="home-name">Our place</span></div>${go('settings',icon('gear'),'round-button','Settings')}</div><h1>All square.<br>Go enjoy the day.</h1><div style="display:flex;align-items:center;gap:20px;margin-top:15px">${orb('all-square-orb','check')}<p style="font-size:15px;max-width:185px">No one owes anyone.<br>Your shared history<br>is right where you left it.</p></div></div>${go('expense',`${orb()}<span><strong>Add an expense</strong><small>For the next “I’ll get this.”</small></span>`,'orb-action')}<div class="section-title"><h2>Latest at home</h2></div>${linkrow('full-repaid','Repayment recorded','You + Sam → Alex + Jo','€84.00',icon('swap','icon-disc lime'))}${linkrow('detail','Dinner together','Alex paid · yesterday','€96.00',icon('dinner','icon-disc orange'))}`,notes('A moment, not a reward system.','All square is a different content state, not an empty one. Retain the last recorded repayment and the shared history.','A one-time check transition is optional; reduced motion uses the same static result.','Separate fixture: the original €84 was repaid in full. No debts were deleted.'),{cls:'empty-home',footer:tabs()});
screen('full-repaid','Record a repayment','Full repayment detail','A complete repayment reconciles to zero.',`${top('Repayment','settled')}<div class="big-check">${icon('check')}</div><h1 class="center">€84 written down.</h1><p class="intro center">You + Sam repaid Alex + Jo.</p><div class="receipt"><div class="number-line"><span>Previously owed</span><b>€84.00</b></div><div class="number-line"><span>Repayment</span><b>−€84.00</b></div><div class="receipt-total"><span>Still owed</span><b>€0.00</b></div></div><p class="confirmation-note center">No one owes anyone.<br>No money was moved by Numa.</p>`,notes('Zero is derived, never wiped.','The recorded amount exactly cancels the preexisting balance.','Back returns to the settled Home fixture.','A repayment record does not independently prove a real-world bank transfer.'),{footer:bottom(primary('Back to our home','settled'))});
screen('offline','Important states','Offline Home','Local-first should be visible when it matters.',homeContent(false,true),notes('Offline, not out of action.','Keep the useful balance and entry action available. One status banner explains that an event is pending.','Details opens the sync recovery state. The app must not present stale remote acknowledgement as “everyone is up to date.”','Your balance includes local pending events. Retry preserves their IDs, order, payload and account boundary.'),{cls:'offline-home',footer:tabs()});
screen('sync-error','Important states','Sync recovery','No repeated saving. No lost history.',`${top('Sync status','offline')}<div class="space-top">${icon('cloud','icon-disc')}</div><h1 style="margin-top:24px">Saved here.<br>Not shared yet.</h1><p class="intro">Your iPhone is keeping 1 pending change.<br>It will sync when the connection returns.</p>${row('Dinner together','Saved locally · waiting to sync','€96.00',icon('dinner','icon-disc orange'))}${expl('Don’t add it again.','The same event will retry. Your household will see it once—not once per attempt.','info')}<p class="small muted">If the server rejects a change, we’ll show the reason and keep the local record for review. We won’t silently discard it.</p>`,notes('Trust comes from a concrete status.','Name what is saved, where it is saved and what still has not happened. No indefinite spinner as the whole screen.','Retry is the same operation identity, not a new expense. Actual server rejection is a distinct state from offline waiting.','This board contains no live network connection. “Retry” previews an unchanged waiting state instead of claiming sync succeeded.'),{footer:bottom(`<button class="primary" data-demo="Offline preview: the existing pending event remains saved. No network request was made.">Try syncing again ${icon('arrow')}</button>`+secondary('Keep using Numa','offline'))});
screen('split-error','Important states','Incomplete split','An error points to the missing amount, not a technical failure.',`${top('Exact amounts','exact')}<h1>€6 still needs<br>a home.</h1><p class="intro">The shares need to add up to €96.00.</p>${switcher('exact')}${groupRow(false,'Your group’s share','€60.00')}${groupRow(true,'Their group’s share','€30.00')}<div class="number-line"><span>Allocated</span><b>€90.00</b></div><div class="number-line"><span>Left to allocate</span><b>€6.00</b></div>${expl('Add the remaining €6.00.','Adjust either group’s share. Nothing has been saved, and your entries are still here.','info')}<p class="form-error">Total must equal the expense amount.</p>`,notes('The fix is in the error.','The title and remaining total expose the missing allocation. Field values stay put.','Review is unavailable until exact integer sums match. “Fix allocation” returns to the completed exact-split preview.','No automatic rounding that loses cents. The reducer receives only a valid exact-sum event.'),{footer:bottom('<button class="primary" disabled>Review expense</button>'+secondary('Fix allocation','exact'))});
screen('large-type','Important states','Larger text','A separate composition—not a shrunk screenshot.',`${top('Your balance','home')}<h1>You + Sam owe<br>Alex + Jo.</h1><div class="space-top">${amount('84.00')}</div><p class="intro">Here’s what makes up<br>your balance.</p>${row('Dinner together','Your group’s share','€48',icon('dinner','icon-disc orange'))}${row('Internet','Your group’s share','€36',icon('wifi','icon-disc lilac'))}<p class="small muted space-top">Repayments recorded: €0.<br>Amounts are in EUR.</p><p class="small muted space-top">Names wrap. Content scrolls.<br>No gesture is required.</p>`,notes('Legibility is part of the design.','At accessibility sizes, paired horizontal groups become a readable sentence and vertical rows. No tiny identity badges or truncated full group names.','Content scrolls above a reserved 64-point action. Production must use actual Dynamic Type, not fixed web pixels.','This is a layout study, not a passed iOS accessibility audit. VoiceOver order, contrast, real text sizes and touch targets still need native verification.'),{cls:'large-type',footer:bottom(primary('Record repayment','repay'))});
screen('system','Design system','Tokens & interaction','One visual grammar, carried through every screen.',`${top('The design language','home')}<h1>A shared table.<br>Not a dashboard.</h1><div class="material-swatch" style="background:var(--butter)">Home surface<span>#F4DE8A</span></div><div class="material-swatch" style="background:var(--lime)">You + Sam<span>#D8EF7F</span></div><div class="material-swatch" style="background:var(--lilac)">Alex + Jo<span>#CAB8ED</span></div><div class="motion-demo">${orb()}<p><strong>One tactile object.</strong><br>Press to add. Never drag to pay.</p></div><div class="section-title"><h2>Human type. Native controls.</h2></div><p class="small muted">Bricolage Grotesque for expressive titles.<br>System text for controls, details and lists.<br>24–25pt edge spacing. 44pt tap minimum.</p>`,notes('Warm, grown-up, unmistakably social.','The direction is “shared table”: warm butter at Home, linen-like neutral elsewhere, citrus and lilac for the two household groups, a glazed terracotta orb. The material itself is code-native geometry, not an AI image.','Glass belongs to navigation in the native build, not every content container. Primary actions stay calm and dark; the orb is the brand’s single physical object.','Owner approved this direction on September 12, 2026. It replaces the rejected violet concept; native implementation and delivery require separate proof. No generated raster, paid image calls, or claimed Figma document.'),{footer:bottom(primary('Explore from Home','home'))});


// Small, explicit presentation scenes preserve the result when navigating Home,
// its explanation and history. These are fixed synthetic examples, not a ledger.
const scenes={
 base:{debt:84,label:'Original household example',kind:'base'},
 equal:{debt:36,label:'After Sam paid €96 · equal split',kind:'expense',ours:48,theirs:48},
 exact:{debt:48,label:'After Sam paid €96 · exact split',kind:'expense',ours:60,theirs:36},
 other:{debt:-12,label:'After Sam paid €96 for Alex + Jo',kind:'expense',ours:0,theirs:96},
 repaid:{debt:34,label:'After recording €50 repaid',kind:'repayment',paid:50},
 overpaid:{debt:-16,label:'After recording €100 repaid',kind:'repayment',paid:100},
 settled:{debt:0,label:'After recording €84 repaid',kind:'repayment',paid:84}
};
let scene='base';
const sceneEntry={'saved':'equal','saved-exact':'exact','saved-paid-for':'other','home-after-expense':'equal','undo':'equal','home-repaid':'repaid','repaid':'repaid','overpaid':'overpaid','settled':'settled','full-repaid':'settled'};
const money=n=>'€'+Math.abs(n).toFixed(2);
const debtSentence=d=>d===0?'No one owes anyone.':d>0?`You + Sam owe Alex + Jo ${money(d)}.`:`Alex + Jo owe You + Sam ${money(d)}.`;
const extraRow=f=>f.kind==='expense'?linkrow('new-expense','Dinner together','Sam paid · today',money(96),icon('dinner','icon-disc orange')):linkrow(f.paid===100?'overpaid':f.paid===84?'full-repaid':'repaid','Repayment recorded','You + Sam → Alex + Jo',money(f.paid),icon('swap','icon-disc lime'));
function sceneFrame(original,id){
 const f=scenes[scene];let s={...original};
 if(scene==='base')return s;
 if(['home','home-after-expense','home-repaid','undo'].includes(id)){
  let h=homeContent().replace('€</span>84','€</span>'+Math.abs(f.debt));
  if(f.debt<0)h=h.replace('You + Sam owe<br>Alex + Jo','Alex + Jo owe<br>You + Sam');
  if(f.debt===0)h=h.replace('You + Sam owe<br>Alex + Jo','All square.<br>No one owes anyone.');
  h=h.replace(linkrow('detail','Dinner together','Alex paid · yesterday','€96.00',icon('dinner','icon-disc orange')),extraRow(f));
  h=h.replace(linkrow('internet','Internet','Jo paid · 10 September','€72.00',icon('wifi','icon-disc lilac')),linkrow('detail','Dinner together','Alex paid · yesterday','€96.00',icon('dinner','icon-disc orange')));
  s.content=h;s.footer=id==='undo'?original.footer:tabs();s.title=id==='undo'?original.title:'Home · '+money(f.debt);s.subtitle=f.label;
 }
 if(id==='why'){
  s.content=`${top('Your balance','home')}<h1>Here’s the<br>whole picture.</h1>${bridge(f.debt<0)}<div class="center">${amount(Math.abs(f.debt).toFixed(2))}<p class="small muted" style="margin-top:7px">${debtSentence(f.debt)}</p></div><div class="section-title"><h2>How it adds up</h2></div>${linkrow('detail','Dinner · Alex paid','Your group’s original share','€48.00',icon('dinner','icon-disc orange'))}${linkrow('internet','Internet · Jo paid','Your group’s original share','€36.00',icon('wifi','icon-disc lilac'))}${f.kind==='expense'?linkrow('new-expense','Dinner · Sam paid','Their share offsets your debt','−'+money(f.theirs),icon('dinner','icon-disc lime')):linkrow(f.paid===100?'overpaid':f.paid===84?'full-repaid':'repaid','Repayment recorded','Your group repaid their group','−'+money(f.paid),icon('swap','icon-disc lime'))}<p class="footnote">${debtSentence(f.debt)}</p>`;
  s.footer=bottom(primary('Back to our home','home'));
 }
 if(['activity','history-expenses','history-repayments'].includes(id)){
  let added=(id==='history-expenses'&&f.kind==='repayment')||(id==='history-repayments'&&f.kind==='expense')?'':extraRow(f);
  s.content=`${top('Activity','home')}<h1>Our running tab.</h1><div class="history-filter">${go('activity','All',id==='activity'?'active':'')}${go('history-expenses','Expenses',id==='history-expenses'?'active':'')}${go('history-repayments','Repayments',id==='history-repayments'?'active':'')}</div><div class="history-summary">${icon('swap')}<p>${debtSentence(f.debt)}</p></div>${added?'<div class="history-day">Today · 12 September</div>'+added:''}${id!=='history-repayments'?`<div class="history-day">11 September</div>${linkrow('detail','Dinner together','Alex paid · added by Jo','€96.00',icon('dinner','icon-disc orange'))}<div class="history-day">10 September</div>${linkrow('internet','Internet','Jo paid · added by Jo','€72.00',icon('wifi','icon-disc lilac'))}`:!added?'<p class="intro">No repayments recorded in this example.</p>':''}`;
  s.footer=tabs('activity');
 }
 if(id==='new-expense'){
  s.content=`${top('Expense','activity')}${icon('dinner','icon-disc orange')}<h1 style="margin-top:18px">Dinner together</h1><p class="intro">12 September 2026</p>${amount('96.00')}<div class="receipt">${row('Paid by Sam','Added by you','',avatar('S'))}${groupRow(false,'Your group’s share',money(f.ours))}${groupRow(true,'Their group’s share',money(f.theirs))}</div><p class="footnote">${debtSentence(f.debt)}</p>`;
  s.footer=bottom(secondary('View shared history','activity'));s.title='New expense · Sam paid';
 }
 if(['home','home-after-expense','home-repaid','undo','why','activity','history-expenses','history-repayments','new-expense'].includes(id)){
  s.notes={...s.notes,trust:`${f.label}. Original debt: €48 dinner share + €36 internet share = €84. ${f.kind==='expense'?`Sam paid €96; the other group's ${money(f.theirs)} share offsets that debt.`:`Your group recorded ${money(f.paid)} repaid.`} Result: ${debtSentence(f.debt)}`};
 }
 if(id==='new-expense')s.notes={lead:'Sam’s new expense. Not yesterday’s bill.',purpose:`Actual payer Sam, recorder You. Own group share ${money(f.ours)}; Alex + Jo share ${money(f.theirs)}. This is the new expense from the selected save flow.`,interaction:'Back opens the matching updated history. Selecting another frame from the studio navigation starts its named independent example.',trust:s.notes.trust};
 return s;
}

const groupOrder=['Start together','Everyday','Add an expense','Record a repayment','Your household','Important states','Design system'];
screens.sort((a,b)=>groupOrder.indexOf(a.section)-groupOrder.indexOf(b.section));
const nav=document.querySelector('#screen-nav'),canvas=document.querySelector('#canvas');let current='home',isBoard=false;
function buildNav(){let last='';nav.innerHTML=screens.map((s,i)=>{const h=s.section!==last?`<div class="nav-section">${s.section}</div>`:'';last=s.section;return h+go(s.id,`<span class="num">${String(i+1).padStart(2,'0')}</span><span>${s.title}</span>`,'screen-link')}).join('')}
function phone(s){return `<div class="artboard-shell" data-frame="${s.id}"><div class="artboard-label">${String(screens.findIndex(x=>x.id===s.id)+1).padStart(2,'0')} / ${s.title} · 393 × 852</div><article class="phone ${s.cls||''}" aria-label="${s.title} iPhone design"><div class="status-bar"><span>9:41</span><span class="island" aria-hidden="true"></span><div class="status-icons" aria-hidden="true"><svg viewBox="0 0 18 14" fill="currentColor"><rect x="0" y="9" width="3" height="5" rx="1"/><rect x="5" y="6" width="3" height="8" rx="1"/><rect x="10" y="3" width="3" height="11" rx="1"/><rect x="15" width="3" height="14" rx="1"/></svg>${icon('wifi')}<span class="battery"></span></div></div><div class="screen-body">${s.content}</div>${s.footer||''}<div class="home-indicator" aria-hidden="true"></div></article></div>`}
function show(id,update=true,reset=false){if(reset){scene='base';document.querySelector('#studio-toast').classList.remove('visible');}if(sceneEntry[id])scene=sceneEntry[id];const original=screens.find(s=>s.id===id)||screens.find(s=>s.id===(id==='new-expense'?'detail':'home'));const s=sceneFrame(original,id);current=id==='new-expense'?'detail':s.id;isBoard=false;document.body.classList.remove('board-mode');document.querySelector('#overview').classList.remove('active');canvas.innerHTML=phone(s);document.querySelector('#screen-title').textContent=s.title;document.querySelector('#screen-subtitle').textContent=s.subtitle+(scene!=='base'?(s.subtitle===scenes[scene].label?'':' · '+scenes[scene].label):['expense','payer','split','exact','paid-for','review','review-exact','review-paid-for','repay','overpay'].includes(id)?' · Starts from the original €84 example':'');document.querySelector('#counter').textContent=`${screens.indexOf(original)+1} / ${screens.length}`;document.querySelector('#notes').innerHTML=`<p class="note-lead">${s.notes.lead}</p><h3>Screen intent</h3><p>${s.notes.purpose}</p><h3>Interaction & motion</h3><p>${s.notes.interaction}</p><h3>Trust & implementation</h3><p>${s.notes.trust}</p><div class="navigation-preview">Click the app’s controls to walk the flow, or use ← / → for every screen in order. Prototype uses named illustrative states, not a live ledger.</div>`;document.querySelectorAll('.screen-link').forEach(x=>{const yes=x.dataset.go===s.id;x.classList.toggle('active',yes);if(yes)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});if(update)history.replaceState(null,'','#'+id);window.scrollTo({top:0,behavior:'instant'})}
function board(){isBoard=true;document.body.classList.add('board-mode');document.body.classList.remove('focus-mode');document.querySelector('#present').classList.remove('active');document.querySelector('#overview').classList.add('active');document.querySelector('#screen-title').textContent='The whole interface';document.querySelector('#screen-subtitle').textContent=`${screens.length} individual screens · click any frame to inspect or walk the flow · all data is illustrative`;document.querySelector('#counter').textContent=`${screens.length} screens`;let last='';canvas.innerHTML=screens.map(s=>{const h=s.section!==last?`<div class="board-section">${s.section}</div>`:'';last=s.section;return h+`<a class="board-link" href="#${s.id}" data-board-go="${s.id}" aria-label="Open ${s.title}">${phone(s)}</a>`}).join('');history.replaceState(null,'','#all')}
let toastTimer;function toast(text){const el=document.querySelector('#studio-toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-board-go]');if(b){e.preventDefault();show(b.dataset.boardGo,true,true);return}const el=e.target.closest('[data-go]');if(el){const target=el.dataset.go;const newExample=['expense','repay','overpay','correction','void','opening','leave','settings','empty'].includes(target);if(newExample&&scene!=='base'&&!el.classList.contains('screen-link')){scene='base';toast('Starting the original €84 example for this separate design flow.')}show(target,true,el.classList.contains('screen-link'));return}const d=e.target.closest('[data-demo]');if(d){toast(d.dataset.demo);return}if(e.target.closest('[data-motion]')){const x=document.querySelector('.motion-demo');x.classList.remove('demo-press');void x.offsetWidth;x.classList.add('demo-press')}});
function step(n){const i=screens.findIndex(s=>s.id===current);show(screens[(i+n+screens.length)%screens.length].id,true,true)}
document.querySelector('#previous').onclick=()=>step(-1);document.querySelector('#next').onclick=()=>step(1);document.querySelector('#overview').onclick=()=>isBoard?show(current):board();document.querySelector('#present').onclick=()=>{if(isBoard)show(current);document.body.classList.toggle('focus-mode');document.querySelector('#present').classList.toggle('active',document.body.classList.contains('focus-mode'))};document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();step(1)}if(e.key==='ArrowLeft'){e.preventDefault();step(-1)}if(e.key==='Escape'&&isBoard)show(current)});window.addEventListener('hashchange',()=>location.hash==='#all'?board():show(location.hash.slice(1),false));
function fitFrame(){document.documentElement.style.setProperty('--preview-scale',Math.max(.5,Math.min(1,(window.innerHeight-224)/852,(window.innerWidth-20)/393)))};fitFrame();window.addEventListener('resize',fitFrame);
buildNav();location.hash==='#all'?board():show(location.hash.slice(1)||'home',false);
// Read-only metadata for review tooling; never contains user data.
window.NUMA_DESIGN={screens:screens.map(({id,section,title,subtitle,notes})=>({id,section,title,subtitle,notes})),version:2,approved:false};

})();
